/*
 * Computes an identity automorphism (i.e. a self-mapping of a graph in which each vertex also maps to itself).
 * @param graph the input graph
 * @param < V > the graph vertex type
 * @param < E > the graph edge type
 * @return a mapping from graph to graph
 */
public static <V,E> IsomorphicGraphMapping<V,E> identity(Graph<V,E> graph){
    // Create a new mapping with the same number of vertices and edges as the input graph
    IsomorphicGraphMapping<V,E> mapping = new IsomorphicGraphMapping<V,E>(graph.getVertices().size(), graph.getEdges().size());

    // Iterate over the vertices of the input graph
    for(V vertex: graph.getVertices()){
        // Add the vertex to the mapping
        mapping.addVertex(vertex);
        // Add the vertex to the mapping again, but this time with a self-loop
        mapping.addVertex(vertex, vertex);
    }

    // Iterate over the edges of the input graph
    for(E edge: graph.getEdges()){
        // Add the edge to the mapping
        mapping.addEdge(edge);
        // Add the edge to the mapping again, but this time with the same source and target vertices
        mapping.addEdge(edge, edge.getSource(), edge.getTarget());
    }

    return mapping;
}

